require(script.Parent.Parent.Parent.Parent.Parent:WaitForChild(".luau-aliases"):WaitForChild("@jsdotlua"):WaitForChild("es7-types"))
return function(list, callback, p)
	local count = #list
	local v

	if p == nil then
		v = 2

		if count == 0 then
			error("reduce of empty array with no initial value")
		end

		p = list[1]
	else
		v = 1
	end

	for i = v, count do
		p = callback(p, list[i], i, list)
	end

	return p
end